// 站方（paizo.libs）把 Date.now 蓋成回 Date 物件、toJSON 也動過，存進 JSON 會變成帶引號的 ISO 字串、之後相減是 NaN。時間戳一律走這個，不要用 Date.now()
const pzNow = () => new Date().getTime();

// ── 夜間模式：自己寫的一套顏色，只蓋 html.pz-dark 底下、而且只蓋腳本認得的東西，不做 Dark Reader 那種整頁反相 ──
// 站方頁首頁尾本來就是深色，不動。改顏色只改這一段；新加的元件要在這裡補一條，否則夜間模式下它會是白的。
const PZ_DARK = (() => { try { return localStorage.getItem('pz.dark') === '1'; } catch (e) { return false; } })();
// pz-dark 的 class 不在這裡加：要等後面認出是 OP 頁／回報頁才加（檔尾選單那段），不然論壇、商店也會半黑半白，而且那些頁沒有選單可以關
// 草稿「送出待確認」：回報頁按儲存時記一筆，下一頁載入時消掉。ok＝這一頁確定是登入狀態的回報頁／OP 頁，才刪那份草稿
const LS_DRAFT_PENDING = 'pz.draftPending';
function settleDraftPending(ok) {
  let p = null; try { p = JSON.parse(localStorage.getItem(LS_DRAFT_PENDING) || 'null'); } catch (e) {}
  if (!p) return;
  try {
    localStorage.removeItem(LS_DRAFT_PENDING);
    if (ok && p.key && pzNow() - (p.t || 0) < 3 * 60 * 1000) localStorage.removeItem(p.key);   // 超過 3 分鐘才載入的頁不算送出的回應，草稿留著
  } catch (e) {}
}
