      const updateSum = () => { let rep = 0, tot = 0; for (const e of evs) { const st = e.shown; if (st) { rep += st.rep; tot += st.n; } } qs('.pz-evsum', head).textContent = evs.length + ' 個活動' + (rep ? ' · 已報 ' + rep + ' 場' : ''); };
