    qsa('h3').forEach(h => { const t = h.textContent.replace(/\s+/g, ' ').trim(); if (SYS[t]) { const hr = h.querySelector('hr'); h.textContent = SYS[t]; if (hr) h.appendChild(hr); } });
    const KIND = { 'Achievement Points': '成就點數', 'Chronicle Boons': '紀錄福利', 'Game Rewards': '遊戲獎勵', 'Playtest Points': '試玩點數' };
    const kindZh = (k) => KIND[k] || k;
